﻿import React from 'react';
import {AbsoluteFill,interpolateColors} from 'remotion';
import {useS,T,en,DUR,Easing,interpolate,clamp,FONT,Destello,Entrar} from './kit';
// DINERO 2026-11-29 09:00 "la perilla que te cobra" (2.5D): volumen (Vol), 3 capas con parallax, giro leve, sombras en el suelo.
// Subtitulos arriba:1330 (debajo de lo principal); la imagen entra 0,2 s antes de cada palabra (EA).
export const SUBS={arriba:1330,size:84,acento:'#FFC83D'};
const S0=[0,15,30,61,77,104,126,147].map(T);
const SB=S0.map((t,i)=>i?t-.15:0);
const EA=(w:string,n=1)=>en(w,n)-.2;
const q=(s:number,a:number,b:number)=>interpolate(s,[a,Math.max(a+.01,b)],[0,1],{...clamp,easing:Easing.inOut(Easing.cubic)});
const pop=(s:number,t0:number)=>interpolate(s,[t0,t0+.38],[0,1],{...clamp,easing:Easing.out(Easing.back(2.2))});
const c01=(v:number)=>Math.max(0,Math.min(1,v));
const mix=(a:number,b:number,u:number)=>a+(b-a)*u;
const ell=(cx:number,cy:number,rx:number,ry:number)=>`M${cx-rx} ${cy}a${rx} ${ry} 0 1 0 ${2*rx} 0a${rx} ${ry} 0 1 0 ${-2*rx} 0Z`;
const rr=(x:number,y:number,w:number,h:number,r:number)=>`M${x+r} ${y}H${x+w-r}A${r} ${r} 0 0 1 ${x+w} ${y+r}V${y+h-r}A${r} ${r} 0 0 1 ${x+w-r} ${y+h}H${x+r}A${r} ${r} 0 0 1 ${x} ${y+h-r}V${y+r}A${r} ${r} 0 0 1 ${x+r} ${y}Z`;
// Capsula cerrada: dedos, brazos y cuellos con volumen (nunca trazos sueltos).
const caps=(x1:number,y1:number,x2:number,y2:number,w:number)=>{const a=Math.atan2(y2-y1,x2-x1),r=w/2,nx=-Math.sin(a)*r,ny=Math.cos(a)*r;
 return `M${x1+nx} ${y1+ny}L${x2+nx} ${y2+ny}A${r} ${r} 0 0 0 ${x2-nx} ${y2-ny}L${x1-nx} ${y1-ny}A${r} ${r} 0 0 0 ${x1+nx} ${y1+ny}Z`;};
type C3=[string,string,string];
const SK:C3=['#d9a070','#9a5a36','#431f0e'],HAIRJ:C3=['#5a463c','#251813','#0a0504'];
const WH:C3=['#ffffff','#e6edf5','#8fa0b4'],CHR:C3=['#ffffff','#b9c5d3','#4a586a'],BLU:C3=['#c4eaff','#2FA8FF','#0a4a99'],HOT:C3=['#ffc0a0','#FF5A2E','#9a1e0a'];
const RED:C3=['#ffb0a0','#FF4D4D','#8a0f1a'],GOLD:C3=['#fff3b0','#FFC83D','#a86a00'],YEL:C3=['#fff2a8','#FFD23F','#a87a00'],PUR:C3=['#d2b4ff','#8A4DFF','#3d1a8a'],TEAL:C3=['#9ff5ea','#19C3B3','#08695f'];
const Vol:React.FC<{id:string;d:string;c:C3;sw?:number;o?:number;borde?:string}>=({id,d,c,sw=70,o=24,borde})=><g>
 <defs><clipPath id={id}><path d={d}/></clipPath></defs>
 <path d={d} fill={c[1]}/>
 <g clipPath={`url(#${id})`}>
  <path d={d} fill='none' stroke={c[2]} strokeWidth={sw} filter='url(#b18)' transform={`translate(${-o} ${-o})`}/>
  <path d={d} fill='none' stroke={c[0]} strokeWidth={sw*.75} filter='url(#b18)' transform={`translate(${o} ${o})`}/>
 </g>
 <path d={d} fill='none' stroke={borde||c[2]} strokeWidth={3} opacity={.55}/>
</g>;
const Brillo2:React.FC<{x:number;y:number;rx:number;ry:number;r?:number;o?:number}>=({x,y,rx,ry,r=-30,o=.75})=><ellipse cx={x} cy={y} rx={rx} ry={ry} transform={`rotate(${r} ${x} ${y})`} fill='#fff' opacity={o} filter='url(#b6)'/>;
const Sombra:React.FC<{x:number;y:number;rx:number;ry:number;o?:number}>=({x,y,rx,ry,o=.35})=><ellipse cx={x} cy={y} rx={rx} ry={ry} fill='#000' opacity={o} filter='url(#b18)'/>;
const Defs:React.FC=()=><defs>
 <filter id='b6' x='-50%' y='-50%' width='200%' height='200%'><feGaussianBlur stdDeviation='6'/></filter>
 <filter id='b18' x='-50%' y='-50%' width='200%' height='200%'><feGaussianBlur stdDeviation='18'/></filter>
 <filter id='b40' x='-50%' y='-50%' width='200%' height='200%'><feGaussianBlur stdDeviation='40'/></filter>
 <radialGradient id='luz'><stop stopColor='#ffffff' stopOpacity='.55'/><stop offset='1' stopColor='#ffffff' stopOpacity='0'/></radialGradient>
 <radialGradient id='vid' cx='.4' cy='.35' r='.85'><stop stopColor='#7fdcff'/><stop offset='.55' stopColor='#1a78e0'/><stop offset='1' stopColor='#06316e'/></radialGradient>
 <linearGradient id='aF' x1='0' y1='0' x2='0' y2='1'><stop stopColor='#9fe8ff'/><stop offset='.5' stopColor='#2FA8FF'/><stop offset='1' stopColor='#0f58c8'/></linearGradient>
 <linearGradient id='aC' x1='0' y1='0' x2='0' y2='1'><stop stopColor='#ffcf8a'/><stop offset='.5' stopColor='#FF5A2E'/><stop offset='1' stopColor='#b3200f'/></linearGradient>
 <linearGradient id='cobre' x1='0' y1='0' x2='1' y2='1'><stop stopColor='#ffd9ab'/><stop offset='.5' stopColor='#e08a33'/><stop offset='1' stopColor='#7a3510'/></linearGradient>
 <linearGradient id='cav' x1='0' y1='0' x2='1' y2='1'><stop stopColor='#1d4d8c'/><stop offset='1' stopColor='#091b3a'/></linearGradient>
 <linearGradient id='tile' x1='0' y1='0' x2='1' y2='1'><stop stopColor='#43ead9'/><stop offset='1' stopColor='#12a899'/></linearGradient>
 <pattern id='azulejo' width='150' height='150' patternUnits='userSpaceOnUse'><rect width='150' height='150' fill='url(#tile)'/><rect x='5' y='5' width='140' height='140' rx='12' fill='none' stroke='#fff' strokeWidth='4' opacity='.4'/><path d='M16 124Q16 16 124 16' fill='none' stroke='#fff' strokeWidth='7' opacity='.25' strokeLinecap='round'/></pattern>
 <radialGradient id='mO' cx='.35' cy='.3'><stop stopColor='#fff6c0'/><stop offset='.5' stopColor='#FFC83D'/><stop offset='1' stopColor='#a86a00'/></radialGradient>
 <radialGradient id='mR' cx='.35' cy='.3'><stop stopColor='#ffc0b0'/><stop offset='.5' stopColor='#FF4D4D'/><stop offset='1' stopColor='#8a0f1a'/></radialGradient>
 <radialGradient id='mA' cx='.35' cy='.3'><stop stopColor='#d8f2ff'/><stop offset='.5' stopColor='#2FA8FF'/><stop offset='1' stopColor='#0a4a99'/></radialGradient>
 <linearGradient id='vino' x1='0' y1='0' x2='0' y2='1'><stop stopColor='#ffffff'/><stop offset='1' stopColor='#cdd8e4'/></linearGradient>
 </defs>;
// ---------- piezas pequenas ----------
const Moneda:React.FC<{x:number;y:number;r?:number;col?:'o'|'r'|'a';melt?:number;rot?:number}>=({x,y,r=40,col='o',melt=0,rot=0})=>{
 const g=col==='o'?'mO':col==='r'?'mR':'mA',ed=col==='o'?'#a86a00':col==='r'?'#8a0f1a':'#0a4a99';
 return <g transform={`translate(${x} ${y}) rotate(${rot}) scale(${1+.35*melt} ${1-.6*melt})`} opacity={1-.9*melt}>
  <ellipse cx={5} cy={r*.8} rx={r*.9} ry={r*.22} fill='#000' opacity={.3} filter='url(#b6)'/>
  <circle r={r} fill={`url(#${g})`} stroke={ed} strokeWidth={4}/><circle r={r*.74} fill='none' stroke='#fff' strokeWidth={3} opacity={.5}/>
  <text y={r*.38} textAnchor='middle' fontSize={r*1.05} fontWeight={900} fontFamily={FONT} fill={ed}>¢</text>
  <Brillo2 x={-r*.4} y={-r*.45} rx={r*.3} ry={r*.14} r={-35}/></g>;};
const Gota:React.FC<{x:number;y:number;r?:number;c?:'r'|'a'|'o'}>=({x,y,r=11,c='r'})=><g transform={`translate(${x} ${y})`}>
 <path d={`M0 ${-r*1.7}C${r*.95} ${-r*.3} ${r} ${r*.5} 0 ${r}C${-r} ${r*.5} ${-r*.95} ${-r*.3} 0 ${-r*1.7}Z`} fill={`url(#m${c==='r'?'R':c==='a'?'A':'O'})`} stroke='#00000044' strokeWidth={2}/><circle cx={-r*.3} cy={-r*.1} r={r*.22} fill='#fff' opacity={.8}/></g>;
const Vapor:React.FC<{x:number;y:number;s:number;n?:number;k?:number;a?:number}>=({x,y,s,n=7,k=1,a=1})=><g opacity={a}>{Array.from({length:n}).map((_,j)=>{const u=(s*.55+j/n)%1;return <circle key={j} cx={x+Math.sin(s*2+j*1.7)*34*k+(j%3-1)*18*k} cy={y-u*330*k} r={(26+u*70)*k} fill='#fff' opacity={(1-u)*.5} filter='url(#b18)'/>;})}</g>;
const Chip:React.FC<{x:number;y:number;txt:string;s:number;t0:number;c?:string;bg?:string;size?:number}>=({x,y,txt,s,t0,c='#FFC83D',bg='#10223f',size=50})=>{const p=pop(s,t0);if(p<=.01)return null;const w=txt.length*size*.66+70;
 return <g transform={`translate(${x} ${y}) scale(${p})`}><rect x={-w/2+6} y={-size*.85+12} width={w} height={size*1.6} rx={24} fill='#000' opacity={.4} filter='url(#b6)'/><rect x={-w/2} y={-size*.85} width={w} height={size*1.6} rx={24} fill={bg} stroke={c} strokeWidth={6}/><text y={size*.36} textAnchor='middle' fill={c} fontSize={size} fontWeight={900} fontFamily={FONT}>{txt}</text></g>;};
const Chispa:React.FC<{x:number;y:number;r:number;rot?:number;c?:string}>=({x,y,r,rot=0,c='#fff'})=><path transform={`translate(${x} ${y}) rotate(${rot})`} d={`M0 ${-r}Q${r*.14} ${-r*.14} ${r} 0Q${r*.14} ${r*.14} 0 ${r}Q${-r*.14} ${r*.14} ${-r} 0Q${-r*.14} ${-r*.14} 0 ${-r}Z`} fill={c}/>;
// ---------- mano con volumen (puntas hacia +x) ----------
const Mano:React.FC<{id:string;x:number;y:number;rot:number;k?:number;pose:'pinza'|'abierta'|'pulgar'}>=({id,x,y,rot,k=1,pose})=>{
 const dedo=(j:number,segs:number[][])=><g key={j}>{segs.map((v,m)=><g key={m}><Vol id={id+'f'+j+m} d={caps(v[0],v[1],v[2],v[3],v[4])} c={SK} sw={22} o={7}/><circle cx={v[2]} cy={v[3]} r={v[4]*.5} fill={SK[1]}/></g>)}
  <ellipse cx={segs[segs.length-1][2]} cy={segs[segs.length-1][3]} rx={segs[segs.length-1][4]*.36} ry={segs[segs.length-1][4]*.3} fill='#f3d2bb' opacity={.85}/></g>;
 if(pose==='pulgar')return <g transform={`translate(${x} ${y}) rotate(${rot}) scale(${k})`}>
  <ellipse cx={14} cy={420} rx={170} ry={26} fill='#000' opacity={.28} filter='url(#b18)'/>
  <Vol id={id+'w'} d={caps(0,420,0,200,140)} c={SK} sw={40} o={12}/>
  <Vol id={id+'cf'} d={caps(0,520,0,330,190)} c={PUR} sw={46} o={13}/>
  <Vol id={id+'p'} d={rr(-122,16,244,236,72)} c={SK} sw={50} o={14}/>
  {[0,1,2,3].map(j=><g key={j}><Vol id={id+'c'+j} d={rr(-112,40+j*54,226,60,30)} c={SK} sw={22} o={7}/>
   <circle cx={-84} cy={70+j*54} r={13} fill={SK[0]} opacity={.7}/><path d={'M76 '+(48+j*54)+'Q92 '+(70+j*54)+' 76 '+(92+j*54)} stroke={SK[2]} strokeWidth={4} fill='none' opacity={.45} strokeLinecap='round'/></g>)}
  <Vol id={id+'th'} d={caps(-44,70,-52,-34,102)} c={SK} sw={34} o={10}/>
  <path d='M-96 22Q-50 38 -4 22' stroke={SK[2]} strokeWidth={4} fill='none' opacity={.5} strokeLinecap='round'/>
  <ellipse cx={-52} cy={-52} rx={33} ry={36} fill='#f6d9c6' stroke={SK[2]} strokeWidth={3} opacity={.92}/><ellipse cx={-62} cy={-65} rx={9} ry={13} fill='#fff' opacity={.7}/>
  <Brillo2 x={-86} y={10} rx={14} ry={46} r={4} o={.4}/><Brillo2 x={-80} y={150} rx={16} ry={70} r={-5} o={.35}/>
 </g>;
 const fing=pose==='pinza'?[[[50,60,104,70,27],[104,70,116,44,23]],[[56,36,110,46,29],[110,46,122,20,24]],[[60,12,112,18,30],[112,18,124,-4,25]]]:[[[55,42,135,70,25],[135,70,175,88,22]],[[62,15,160,28,29],[160,28,212,38,25]],[[65,-15,165,-20,30],[165,-20,222,-22,26]]];
 const idx=pose==='pinza'?[[55,-40,120,-50,30],[120,-50,148,-18,26]]:[[60,-45,150,-70,30],[150,-70,200,-82,26]];
 const th=pose==='pinza'?[[15,48,90,72,34],[90,72,128,38,28]]:[[10,52,70,115,34],[70,115,105,160,28]];
 return <g transform={`translate(${x} ${y}) rotate(${rot}) scale(${k})`}>
  <ellipse cx={14} cy={22} rx={120} ry={80} fill='#000' opacity={.25} filter='url(#b18)'/>
  {fing.map((f,j)=>dedo(j,f as number[][]))}
  <Vol id={id+'pa'} d='M-72 -62C-20 -86 40 -80 75 -55C102 -35 102 35 75 58C40 82 -20 86 -72 62C-92 30 -92 -30 -72 -62Z' c={SK} sw={70} o={20}/>
  {[0,1,2].map(j=><circle key={j} cx={62} cy={-26+j*26} r={9} fill={SK[0]} opacity={.65}/>)}
  <Brillo2 x={-10} y={-40} rx={40} ry={14} r={-10} o={.45}/>
  {dedo(8,idx)}{dedo(9,th)}
 </g>;};
// Boton de temperatura: FRIA azul a la izquierda, CALIENTE roja a la derecha; la palanca gira con ang (-60..60).
const pt=(r:number,a:number):[number,number]=>[r*Math.sin(a*Math.PI/180),-r*Math.cos(a*Math.PI/180)];
const arco=(r:number,a0:number,a1:number)=>{const [x0,y0]=pt(r,a0),[x1,y1]=pt(r,a1);return `M${x0} ${y0}A${r} ${r} 0 0 1 ${x1} ${y1}`;};
const Perilla:React.FC<{id:string;x:number;y:number;k:number;ang:number}>=({id,x,y,k,ang})=>{
 const fr=c01((-ang-10)/30),ca=c01((ang-10)/30),lz=c01((ang+60)/120);
 const tc:C3=[interpolateColors(lz,[0,1],['#c4eaff','#ffc0a0']),interpolateColors(lz,[0,1],['#2FA8FF','#FF5A2E']),interpolateColors(lz,[0,1],['#0a4a99','#9a1e0a'])];
 return <g transform={`translate(${x} ${y}) scale(${k})`}>
  <ellipse cx={20} cy={36} rx={264} ry={264} fill='#000' opacity={.32} filter='url(#b18)'/>
  <Vol id={id+'p'} d={ell(0,0,250,250)} c={WH} sw={90} o={26}/>
  <path d={arco(205,-66,-4)} stroke='#2FA8FF' strokeWidth={26} fill='none' strokeLinecap='round' opacity={.3+.7*fr}/>
  <path d={arco(205,4,66)} stroke='#FF5A2E' strokeWidth={26} fill='none' strokeLinecap='round' opacity={.3+.7*ca}/>
  {[-60,-45,-30,-15,0,15,30,45,60].map(a=>{const p0=pt(170,a),p1=pt(188,a);return <path key={a} d={`M${p0[0]} ${p0[1]}L${p1[0]} ${p1[1]}`} stroke='#42546d' strokeWidth={5} strokeLinecap='round'/>;})}
  {[-1,1].map(sg=>{const [lx,ly]=pt(205,sg*74),on=sg<0?fr:ca;return <g key={sg}><circle cx={lx} cy={ly} r={70} fill={sg<0?'#2FA8FF':'#FF3B1F'} opacity={on*.8} filter='url(#b18)'/><circle cx={lx} cy={ly} r={21} fill={interpolateColors(on,[0,1],[sg<0?'#1a3350':'#4a1a18',sg<0?'#7fdcff':'#ff4a2a'])} stroke='#fff' strokeWidth={4} opacity={.95}/><circle cx={lx-6} cy={ly-7} r={6} fill='#fff' opacity={.5+.5*on}/></g>;})}
  <text x={-84} y={186} textAnchor='middle' fontSize={32} fontWeight={900} fontFamily={FONT} fill='#1c78d8'>FRÍA</text>
  <text x={92} y={186} textAnchor='middle' fontSize={32} fontWeight={900} fontFamily={FONT} fill='#e03a18'>CALIENTE</text>
  <Vol id={id+'k'} d={ell(0,0,126,126)} c={CHR} sw={60} o={20}/>
  {Array.from({length:28}).map((_,j)=>{const a=j*360/28,p0=pt(112,a),p1=pt(126,a);return <path key={j} d={`M${p0[0]} ${p0[1]}L${p1[0]} ${p1[1]}`} stroke='#3a4658' strokeWidth={4} opacity={.55}/>;})}
  <Vol id={id+'i'} d={ell(0,0,84,84)} c={['#aebccb','#e6edf5','#ffffff']} sw={40} o={12}/>
  <g transform={`rotate(${ang})`}><Vol id={id+'l'} d={caps(0,-30,0,-150,38)} c={tc} sw={26} o={9}/><circle cy={-150} r={26} fill={tc[1]} stroke={tc[2]} strokeWidth={3}/><circle cx={-7} cy={-158} r={8} fill='#fff' opacity={.8}/></g>
  <Brillo2 x={-62} y={-72} rx={40} ry={16} r={-40} o={.7}/>
 </g>;};
// Perilla + mano pinzando la palanca (el antebrazo sale de un ancla fija; con manga si se pide).
const PerillaMano:React.FC<{id:string;x:number;y:number;k:number;ang:number;anchor?:[number,number];off?:[number,number];manga?:boolean}>=({id,x,y,k,ang,anchor=[1260,2080],off=[0,0],manga=false})=>{
 const [tx,ty]=pt(150,ang),px=x+tx*k+off[0],py=y+ty*k+off[1],th=Math.atan2(py-anchor[1],px-anchor[0]),ca=Math.cos(th),sa=Math.sin(th),kk=k*.78;
 const hx=px-(ca*142-sa*8)*kk,hy=py-(sa*142+ca*8)*kk,wx=hx-ca*72*kk,wy=hy-sa*72*kk,bx=wx-ca*50*kk,by=wy-sa*50*kk,nx=-sa*60*kk,ny=ca*60*kk;
 return <g><Perilla id={id} x={x} y={y} k={k} ang={ang}/>
  <Vol id={id+'a'} d={caps(anchor[0],anchor[1],wx,wy,118*kk)} c={SK} sw={50} o={14}/>
  {manga&&<Vol id={id+'m'} d={caps(anchor[0],anchor[1],anchor[0]+(wx-anchor[0])*.3,anchor[1]+(wy-anchor[1])*.3,150*kk)} c={PUR} sw={50} o={14}/>}
  <Vol id={id+'b'} d={caps(bx-nx,by-ny,bx+nx,by+ny,22*kk)} c={GOLD} sw={12} o={4}/>
  <Mano id={id+'h'} x={hx} y={hy} rot={th*180/Math.PI} k={kk} pose='pinza'/></g>;};
// ---------- lavadora de frente ----------
const Tambor:React.FC<{id:string;x:number;y:number;R:number;s:number;fill:number;hot:number;giro?:number;children?:React.ReactNode}>=({id,x,y,R,s,fill,hot,giro=1,children})=>{
 const surf=R-fill*2*R,wave=()=>{let d=`M${-R-10} ${surf+Math.sin(-R*.03+s*3)*6}`;for(let xx=-R+20;xx<=R+10;xx+=30)d+=`L${xx} ${surf+Math.sin(xx*.03+s*3)*6}`;return d+`L${R+10} ${R+10}L${-R-10} ${R+10}Z`;};
 return <g transform={`translate(${x} ${y})`}>
  <defs><clipPath id={id+'c'}><circle r={R}/></clipPath></defs>
  <circle r={R} fill='url(#vid)'/>
  <g clipPath={`url(#${id}c)`}>
   {[.82,.58,.34].map((f,rIx)=>Array.from({length:14+rIx*-2}).map((_,j)=>{const a=j*360/(14-rIx*2)+s*28*giro*(rIx%2?-1:1),p=pt(R*f,a);return <circle key={rIx+'_'+j} cx={p[0]} cy={p[1]} r={R*.022} fill='#0a3a82' opacity={.55}/>;}))}
   <g opacity={.5} transform={`rotate(${s*45*giro})`}>{[0,1,2].map(j=><path key={j} d={`M0 0L${R*Math.cos(j*2.09)} ${R*Math.sin(j*2.09)}`} stroke='#0a3a82' strokeWidth={R*.08} strokeLinecap='round'/>)}</g>
   <path d={wave()} fill='url(#aF)' opacity={(1-hot)*.88}/><path d={wave()} fill='url(#aC)' opacity={hot*.88}/>
   {fill>.02&&<path d={`M${-R} ${surf+Math.sin(-R*.03+s*3)*6}`+Array.from({length:14}).map((_,j)=>`L${-R+j*R/6.5} ${surf+Math.sin((-R+j*R/6.5)*.03+s*3)*6}`).join('')} stroke='#fff' strokeWidth={5} fill='none' opacity={.55}/>}
   {fill>.02&&Array.from({length:16}).map((_,j)=>{const u=(s*.55+j*.137)%1,by=R*.9-u*(R*.9-surf-5);return by>surf?<g key={j}><circle cx={-R*.8+((j*47)%100)/100*R*1.6+Math.sin(s*2+j)*10} cy={by} r={R*(.025+(j%4)*.012)} fill='#fff' opacity={.25} stroke='#fff' strokeWidth={2}/></g>:null;})}
   {children}
  </g></g>;};
const Lav:React.FC<{id:string;x:number;y:number;k:number;s:number;ang?:number;cierra?:number;children?:React.ReactNode;tam?:React.ReactNode}>=({id,x,y,k,s,ang=-60,cierra=1,children,tam})=><g transform={`translate(${x} ${y}) scale(${k})`}>
 <Sombra x={0} y={545} rx={410} ry={48} o={.42}/>
